class TtlCache:
    def __init__(self, clock):
        self._clock = clock
        self._entries = {}

    def set(self, key, value, ttl_seconds):
        self._entries[key] = (value, self._clock() + ttl_seconds)

    def get(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if self._clock() <= expires_at:
            return value
        del self._entries[key]
        return None

