class DependencyGraph:
    def __init__(self):
        self._dependencies = {}

    def add_node(self, node):
        self._dependencies.setdefault(node, set())

    def add_dependency(self, node, dependency):
        self.add_node(node)
        self.add_node(dependency)
        self._dependencies[node].add(dependency)

